WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM sessions), sessions_sessions AS (SELECT id, customer_id, browser, started_at, country, SUM(is_new_session) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT country, ROUND(AVG(island_id), 2) AS avg_island_id, MIN(started_at) AS started_at, ROUND(SUM(island_id) / NULLIF(COUNT(CASE WHEN country = 'TH' THEN 1 END), 0), 2) AS island_id_per_th FROM sessions_sessions GROUP BY country ORDER BY island_id_per_th DESC;
